function buildDefaultGradesForRange(min3, max3, count2 = 3, semantic = "risk") {
  if (max3 <= min3) max3 = min3 + 1;
  const span = max3 - min3;
  const seg = Math.ceil(span / count2);
  const colors = ["#10B981", "#F59E0B", "#F97316", "#EF4444", "#7C3AED"];
  const labels = ["A", "B", "C", "D", "E"];
  const results = [];
  for (let i = 0; i < count2; i++) {
    const lo = min3 + i * seg;
    const hi = i === count2 - 1 ? max3 : Math.min(max3, lo + seg - 1);
    const idx = semantic === "credit" ? i : count2 - 1 - i;
    const g = labels[idx] ?? labels[labels.length - 1];
    results.push({
      grade: g,
      label: g,
      minScore: lo,
      maxScore: hi,
      riskLevel: idx === 0 ? "\u4F4E" : idx === 1 ? "\u4E2D" : "\u9AD8",
      color: colors[idx % colors.length],
      tags: "",
      // 风险标签（空格分隔）默认空，配置页可编辑，保证 JSON 始终有记录
      autoResult: idx === 0 ? "\u901A\u8FC7" : idx === count2 - 1 ? "\u62D2\u7EDD" : "\u8F6C\u4EBA\u5DE5",
      description: `\u5206\u6BB5 ${g}`
    });
  }
  return results;
}
