function computeScoreSummary(t) {
  const rows = t.sections.filter((s) => (s.homeTab ?? "content") === "content").sort((a, b) => a.order - b.order).map((s) => {
    const r2 = computeSectionScore(s);
    const w = s.weight ?? 1;
    const rejectItems = r2.mode === "reject" ? s.fields.filter((f2) => f2.visible).length : s.fields.filter((f2) => f2.visible && f2.hitReject).length;
    return {
      id: s.id,
      name: s.sourceName || s.name,
      sourceType: s.sourceType,
      mode: r2.mode,
      countedItems: r2.mode === "add" ? r2.addCount : r2.deductCount,
      points: r2.total * w,
      weight: w,
      rejectItems,
      visible: s.visible
    };
  });
  const enabled = rows.filter((r2) => r2.visible);
  const addMax = enabled.reduce((sum2, r2) => sum2 + (r2.mode === "add" ? r2.points : 0), 0);
  const deductMax = enabled.reduce((sum2, r2) => sum2 + (r2.mode === "deduct" ? -r2.points : 0), 0);
  const baseScore = t.scoreDisplay.baseScore ?? 0;
  const formula = t.scoreFormula ?? buildDefaultScoreFormula(t.sections);
  const rawTotals = {};
  for (const s of t.sections.filter((s2) => (s2.homeTab ?? "content") === "content")) {
    const r2 = computeSectionScore(s);
    rawTotals[s.id] = Math.abs(r2.total);
  }
  const maxVals = {};
  const minVals = {};
  for (const term of formula.terms) {
    if (term.kind === "var" && term.varId) {
      const secId = term.varId.replace("sec_", "");
      const raw = rawTotals[secId] ?? 0;
      maxVals[term.varId] = term.op === "+" ? raw : 0;
      minVals[term.varId] = term.op === "-" ? raw : 0;
    }
  }
  const formulaMax = evaluateFormula(formula, maxVals) ?? 0;
  const formulaMin = evaluateFormula(formula, minVals) ?? 0;
  const specialRejectCount = (t.specialRules ?? []).filter((r2) => r2.autoResult === "\u62D2\u7EDD").length;
  return {
    rows,
    baseScore,
    addMax,
    deductMax,
    min: baseScore + formulaMin,
    max: baseScore + formulaMax,
    // 9.5.1 命中即拒 = 特殊命中规则中「命中-拒绝」的条目总数（用户定义；不再累加字段级命中即拒项）
    rejectTotal: specialRejectCount
  };
}
function validateGrades(grades, min3, max3) {
  const errs = [];
  if (!grades.length) return ["\u5C1A\u672A\u914D\u7F6E\u4EFB\u4F55\u5206\u6BB5"];
  const sorted = [...grades].sort((a, b) => a.minScore - b.minScore);
  for (const g of sorted) if (g.minScore > g.maxScore) errs.push(`\u300C${g.grade}\u300D\u533A\u95F4\u4E0B\u9650\u5927\u4E8E\u4E0A\u9650\uFF08${g.minScore}~${g.maxScore}\uFF09`);
  for (let i = 1; i < sorted.length; i++) {
    const prev2 = sorted[i - 1], cur = sorted[i];
    if (cur.minScore <= prev2.maxScore) errs.push(`\u300C${prev2.grade}\u300D\u4E0E\u300C${cur.grade}\u300D\u533A\u95F4\u91CD\u53E0`);
    else if (cur.minScore > prev2.maxScore + 1) errs.push(`\u300C${prev2.grade}\u300D\u4E0E\u300C${cur.grade}\u300D\u4E4B\u95F4\u6709\u7F1D\u9699\uFF08${prev2.maxScore + 1}~${cur.minScore - 1} \u65E0\u5F52\u5C5E\uFF09`);
  }
  if (sorted[0].minScore > min3) errs.push(`\u603B\u5206\u4E0B\u9650 ${min3} \u672A\u8986\u76D6\uFF08\u6700\u4F4E\u5206\u6BB5\u4ECE ${sorted[0].minScore} \u8D77\uFF09`);
  if (sorted[sorted.length - 1].maxScore < max3) errs.push(`\u603B\u5206\u4E0A\u9650 ${max3} \u672A\u8986\u76D6\uFF08\u6700\u9AD8\u5206\u6BB5\u5230 ${sorted[sorted.length - 1].maxScore} \u6B62\uFF09`);
  return errs;
}
function gradeForScore(t, score) {
  const g = t.scoreDisplay.grades.find((x) => score >= x.minScore && score <= x.maxScore);
  return g ?? t.scoreDisplay.grades[t.scoreDisplay.grades.length - 1];
}
function syncFlowToGrades(flow, grades) {
  const calc = flow[0] ?? defaultFlowRow("\u2014", "\u7CFB\u7EDF\u6B63\u5728\u8BA1\u7B97\u8BC4\u5206\uFF0C\u8BF7\u7A0D\u5019\u2026");
  const per = grades.map((g, i) => {
    const prev2 = flow[i + 1];
    return prev2 ? { ...prev2, gradeId: g.grade } : defaultFlowRow(g.grade, `${g.label}\uFF0C\u8BF7\u914D\u7F6E\u5904\u7F6E\u7B56\u7565`);
  });
  return [calc, ...per];
}
